<!-- wp:wdl/custom-title-accordion-1 {"subTitle":"FIRST VISIT","mainTitle":"はじめての方から","headingLevel":3,"mainTitleColor":"#46688c","borderColor":"#46688c","borderWidth":1,"backgroundColor":"#f1f5f9","iconColor":"#46688c"} -->
<h3 class="wp-block-wdl-custom-title-accordion-1 custom-title-accordion-1" style="border-color:#46688c;border-width:1px;border-style:solid;background-color:#f1f5f9"><span class="sub" style="color:#46688c">FIRST VISIT</span><span class="main">はじめての方から</span><span class="accordion-icon" style="background:#46688c" data-icon="true"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 448 512"><path d="M438.6 278.6c12.5-12.5 12.5-32.8 0-45.3l-160-160c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3L338.8 224H32c-17.7 0-32 14.3-32 32s14.3 32 32 32h306.8l-111.9 111.9c-12.5 12.5-12.5 32.8 0 45.3s32.8 12.5 45.3 0l160-160z"></path></svg></span></h3><script>
/* === accordionScript – window.load 待機 & .last_content 判定付き ============ */
(function () {
	const scriptEl = document.currentScript;

	const run = () => {
		if (!scriptEl) return;
		if (document.body.classList.contains('block-editor-page')) return;

		const heading = scriptEl.previousElementSibling;
		if (!heading || !heading.classList.contains('custom-title-accordion-1')) return;
		if (heading.__lwAccBound) return;
		heading.__lwAccBound = true;

		const wrap = document.createElement('div');
		wrap.className = 'custom-title-accordion-1__content_wrap';
		wrap.style.display = 'none';

		const sameTag = heading.tagName;
		let node = scriptEl.nextSibling;

		while (
			node &&
			!(
				node.nodeType === 1 &&
				(node.tagName === sameTag || node.classList?.contains('last_content'))
			)
		) {
			const next = node.nextSibling;
			wrap.appendChild(node);
			node = next;
		}
		if (!wrap.childNodes.length) return;

		heading.parentNode.insertBefore(wrap, node);

		heading.addEventListener('click', () => {
			const hidden = wrap.style.display === 'none';
			wrap.style.display = hidden ? '' : 'none';
			heading.classList.toggle('open', hidden);
		});
	};

	if (document.readyState === 'complete') {
		run();
	} else {
		window.addEventListener('load', run, { once: true });
	}
})();
</script>
<!-- /wp:wdl/custom-title-accordion-1 -->
<!-- wp:wdl/lw-qa-1 {"FontLabel":"Roboto","mainColor":"#46688c"} -->
<div class="wp-block-wdl-lw-qa-1 lw-qa-1"><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#46688c"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">予約は必要ですか</p></div><div class="open_icon" style="background:#46688c"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#46688c">A<div style="background:#46688c"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">必要です。1名ずつのご案内のため、当日でもお電話をいただけると確実です。空いていればその日のうちにお受けできます。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#46688c"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">何を持っていけば</p></div><div class="open_icon" style="background:#46688c"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#46688c">A<div style="background:#46688c"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">手ぶらでお越しください。着替え・タオル・メイク落としはこちらでご用意しています。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#46688c"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">当日は何分かかる</p></div><div class="open_icon" style="background:#46688c"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#46688c">A<div style="background:#46688c"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">初回はカウンセリングを含めて90分ほどです。2回目からは、部位によって30〜60分です。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#46688c"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">自己処理は必要</p></div><div class="open_icon" style="background:#46688c"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#46688c">A<div style="background:#46688c"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">前日までにご自宅で剃ってきていただけると助かります。剃り残しはこちらで整えますので、無理をなさらないでください。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#46688c"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">生理中でも大丈夫</p></div><div class="open_icon" style="background:#46688c"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#46688c">A<div style="background:#46688c"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">デリケートゾーン以外はお受けできます。体調によっては見送ることもありますので、当日にお申し出ください。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#46688c"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">途中でやめられる</p></div><div class="open_icon" style="background:#46688c"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#46688c">A<div style="background:#46688c"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">やめられます。回数の残りは規定に沿って返金いたします。違約金はいただきません。</p></div></dd></dl><script>
(function(){
	const scriptEl  = document.currentScript;
	if ( !scriptEl ) return;
	const container = scriptEl.parentNode;           // <script> の親 = lw-qa-1 本体
	if ( !container || !container.classList.contains('lw-qa-1') ) return;

	/* クリックイベントをバインド ---------------------- */
	function bind () {
		container.querySelectorAll(".lw-qa-1__dl").forEach( function( dl ){
			if ( dl.dataset.lwQaBound ) return;      // 二重バインド防止
			dl.dataset.lwQaBound = "1";
			dl.addEventListener("click", function(){ dl.classList.toggle("active"); } );
		} );
	}

	bind(); // まず 1 回

	/* MutationObserver – QA が動的に増減しても OK */
	const mo = new MutationObserver(bind);
	mo.observe(container,{ childList:true, subtree:true });
})();
		</script></div>
